runScript("\n(function(){\n  function build(){\n    var grids=[].slice.call(document.querySelectorAll('.scents'));\n    if(!grids.length){ return; }\n    var grid=grids[0];\n    if(grid.getAttribute('data-api-built')==='1'){ return; }\n    grids.forEach(function(g){ g.querySelectorAll('.card-scent').forEach(function(c){ c.parentNode.removeChild(c); }); });\n    grids.forEach(function(g,i){ if(i>0){ g.style.display='none'; } });\n    var apis=[\n      {badge:'POST /v1/twins', name:'Olfactory Digital Twins', desc:'simulate how a whole population perceives a formula before you ever mix it.', viz:'twin', code:['POST /v1/twins','{','  \"formula\": \"blend_07\",','  \"population\": \"global\"','}','\\u2192 perception map']},\n      {badge:'POST /v1/receptor', name:'Olfactory Receptor', desc:'predict receptor-level binding and activation for any molecule.', viz:'receptor', code:['POST /v1/receptor','{','  \"molecule\": \"linalool\"','}','\\u2192 binding: 0.82']},\n      {badge:'POST /v1/cortex', name:'Olfactory Cortex', desc:'model the downstream neural and emotional response to a scent.', viz:'cortex', code:['POST /v1/cortex','{','  \"scent\": \"blend_07\"','}','\\u2192 response model']}\n    ];\n    function viz(kind){\n      if(kind==='twin'){ return '<svg viewBox=\"0 0 300 84\" width=\"100%\" height=\"84\" preserveAspectRatio=\"xMidYMid meet\"><g opacity=\"0.95\"><path d=\"M80 42L120 24M80 42L120 60M120 24L160 42M120 60L160 42\" stroke=\"rgba(124,77,255,0.5)\" stroke-width=\"1\"/><circle cx=\"80\" cy=\"42\" r=\"3\" fill=\"#c8b6ff\" class=\"apx-pulse\" style=\"--d:0s\"/><circle cx=\"120\" cy=\"24\" r=\"2.5\" fill=\"#a98bff\" class=\"apx-pulse\" style=\"--d:.4s\"/><circle cx=\"120\" cy=\"60\" r=\"2.5\" fill=\"#a98bff\" class=\"apx-pulse\" style=\"--d:.8s\"/><circle cx=\"160\" cy=\"42\" r=\"3\" fill=\"#8f6bff\" class=\"apx-pulse\" style=\"--d:1.2s\"/></g><g opacity=\"0.45\" transform=\"translate(40,0)\"><path d=\"M80 42L120 24M80 42L120 60M120 24L160 42M120 60L160 42\" stroke=\"rgba(91,139,255,0.4)\" stroke-width=\"1\"/><circle cx=\"80\" cy=\"42\" r=\"3\" fill=\"#5b8bff\" class=\"apx-pulse\" style=\"--d:.2s\"/><circle cx=\"120\" cy=\"24\" r=\"2.5\" fill=\"#5b8bff\" class=\"apx-pulse\" style=\"--d:.6s\"/><circle cx=\"120\" cy=\"60\" r=\"2.5\" fill=\"#5b8bff\" class=\"apx-pulse\" style=\"--d:1s\"/><circle cx=\"160\" cy=\"42\" r=\"3\" fill=\"#5b8bff\" class=\"apx-pulse\" style=\"--d:1.4s\"/></g></svg>'; }\n      if(kind==='receptor'){ return '<svg viewBox=\"0 0 300 84\" width=\"100%\" height=\"84\" preserveAspectRatio=\"xMidYMid meet\"><circle cx=\"150\" cy=\"42\" r=\"10\" fill=\"none\" stroke=\"#8f6bff\" stroke-width=\"1.5\"/><circle cx=\"150\" cy=\"42\" r=\"4\" fill=\"#7c4dff\" class=\"apx-pulse\" style=\"--d:0s\"/><circle class=\"apx-incoming\" cx=\"60\" cy=\"42\" r=\"3.5\" fill=\"#c8b6ff\"/><path d=\"M170 42h40M170 36h28M170 48h28\" stroke=\"rgba(124,77,255,0.5)\" stroke-width=\"1.2\"/><circle cx=\"216\" cy=\"42\" r=\"3\" fill=\"#5b8bff\" class=\"apx-pulse\" style=\"--d:.7s\"/></svg>'; }\n      return '<svg viewBox=\"0 0 300 84\" width=\"100%\" height=\"84\" preserveAspectRatio=\"xMidYMid meet\"><path class=\"apx-wave\" d=\"M20 60 L60 60 L75 30 L95 60 L115 20 L135 60 L155 40 L280 40\" stroke=\"#7c4dff\" stroke-width=\"1.6\" fill=\"none\"/><circle class=\"apx-rider\" cx=\"20\" cy=\"60\" r=\"3\" fill=\"#c8b6ff\"/><path d=\"M20 72 L280 72\" stroke=\"rgba(255,255,255,0.08)\" stroke-width=\"1\"/></svg>';\n    }\n    function codeBlock(lines){ var html=''; for(var i=0;i<lines.length;i++){ var ln=lines[i].split('<').join('&lt;'); var cls='apx-cl'; if(i===0){ cls+=' apx-cmethod'; } if(lines[i].indexOf('\\u2192')===0){ cls+=' apx-cret'; } html+='<div class=\"'+cls+'\">'+ln+'</div>'; } return '<div class=\"apx-code\">'+html+'</div>'; }\n    var css=document.createElement('style'); css.setAttribute('data-apx','1');\n    css.textContent='.scents{grid-template-columns:repeat(3, minmax(0,1fr)) !important;gap:20px !important;}@media (max-width:991px){.scents{grid-template-columns:repeat(2,minmax(0,1fr)) !important;}}@media (max-width:767px){.scents{grid-template-columns:1fr !important;}}.apx-card{position:relative;font-family:Figtree,sans-serif;background:linear-gradient(160deg,rgba(72,22,245,0.12),rgba(255,255,255,0.03)),hsl(282,75%,8%);border:1px solid rgba(255,255,255,0.12);border-radius:20px;padding:24px;overflow:hidden;display:flex;flex-direction:column;min-height:440px;transition:border-color .3s ease,transform .3s ease;}.apx-card:hover{border-color:rgba(124,77,255,0.6);transform:translateY(-4px);}.apx-card::before{content:\"\";position:absolute;inset:0;background:radial-gradient(circle at 80% 0%,rgba(124,77,255,0.18),transparent 55%);pointer-events:none;}.apx-badge{position:relative;display:inline-flex;align-items:center;gap:6px;font-family:ui-monospace,Menlo,monospace;font-size:10.5px;letter-spacing:.06em;text-transform:uppercase;color:#b3aafb;background:rgba(72,22,245,0.18);border:1px solid rgba(124,77,255,0.3);padding:5px 9px;border-radius:6px;width:fit-content;}.apx-bdot{width:6px;height:6px;border-radius:50%;background:#7c4dff;box-shadow:0 0 8px 2px rgba(124,77,255,0.8);animation:apxBlink 1.8s ease-in-out infinite;}.apx-viz{position:relative;height:84px;margin:18px 0 16px;border-radius:12px;background:rgba(0,0,0,0.25);border:1px solid rgba(255,255,255,0.06);overflow:hidden;}.apx-name{position:relative;font-size:20px;font-weight:600;color:#fff;letter-spacing:-.01em;margin:0 0 6px;}.apx-desc{position:relative;font-size:13px;line-height:1.5;color:rgba(255,255,255,.6);margin:0 0 18px;}.apx-code{position:relative;margin-top:auto;font-family:ui-monospace,Menlo,monospace;font-size:11.5px;line-height:1.7;background:rgba(0,0,0,0.35);border:1px solid rgba(255,255,255,0.08);border-radius:10px;padding:12px 14px;color:rgba(255,255,255,0.75);}.apx-cmethod{color:#b3aafb;letter-spacing:.04em;margin-bottom:4px;}.apx-cret{color:#8f6bff;margin-top:4px;}@keyframes apxBlink{0%,100%{opacity:1}50%{opacity:.3}}.apx-pulse{animation:apxPulse 2.4s ease-in-out infinite;animation-delay:var(--d,0s);transform-box:fill-box;transform-origin:center;}@keyframes apxPulse{0%,100%{opacity:.5;}50%{opacity:1;}}.apx-incoming{animation:apxIncoming 2.6s ease-in-out infinite;}@keyframes apxIncoming{0%{transform:translateX(0);opacity:0;}30%{opacity:1;}70%{transform:translateX(86px);opacity:1;}100%{transform:translateX(86px);opacity:0;}}';\n    document.head.appendChild(css);\n    apis.forEach(function(a){ var d=document.createElement('div'); d.className='apx-card'; d.innerHTML='<span class=\"apx-badge\"><span class=\"apx-bdot\"></span>'+a.badge+'</span><div class=\"apx-viz\">'+viz(a.viz)+'</div><h3 class=\"apx-name\">'+a.name+'</h3><p class=\"apx-desc\">'+a.desc+'</p>'+codeBlock(a.code); grid.appendChild(d); });\n    var rider=grid.querySelector('.apx-rider'); var wave=grid.querySelector('.apx-wave');\n    if(rider){ if(wave){ try{ var len=wave.getTotalLength(); var t0=null,dur=3000; function step(now){ if(t0===null)t0=now; var p=((now-t0)%dur)/dur; var pt=wave.getPointAtLength(p*len); rider.setAttribute('cx',pt.x); rider.setAttribute('cy',pt.y); requestAnimationFrame(step);} requestAnimationFrame(step);}catch(e){} }}\n    if(grid.parentElement){ grid.parentElement.style.marginTop='28px'; }\n    var sub=null, ps=document.querySelectorAll('p');\n    for(var pi=0; pi<ps.length; pi++){ if(/Each of our aroma blends/i.test(ps[pi].textContent)){ sub=ps[pi]; break; } }\n    if(sub){ sub.textContent='Neural AI turns the science of scent perception into models developers can build on, predicting and customizing how any scent is experienced.'; sub.style.alignSelf='flex-start'; }\n    var npTitle=null, hs=document.querySelectorAll('h1');\n    for(var hi=0; hi<hs.length; hi++){ if(/Foundational Neural Models/i.test(hs[hi].textContent)){ npTitle=hs[hi]; break; } }\n    if(npTitle){ if(npTitle.parentElement){ if(!document.getElementById('np-section-pill')){\n      var pill=document.createElement('span'); pill.id='np-section-pill'; pill.textContent='Neural AI';\n      pill.style.cssText='display:inline-flex;align-self:flex-start;align-items:center;font-family:Figtree,sans-serif;background:rgba(72,22,245,0.15);border:1px solid rgba(124,77,255,0.3);border-radius:999px;padding:6px 14px;color:#b3aafb;font-size:11px;font-weight:600;letter-spacing:0.88px;text-transform:uppercase;margin-bottom:16px;width:fit-content;';\n      npTitle.parentElement.insertBefore(pill, npTitle);\n    }}}\n    grid.setAttribute('data-api-built','1');\n  }\n  if(document.readyState!=='loading'){ build(); } else { document.addEventListener('DOMContentLoaded',build); }\n  setTimeout(build,500); setTimeout(build,1500);\n})();\n");
runScript("\n(function(){\n  function styleTitle(){\n    var hs=document.querySelectorAll('h1.sp-h1');\n    for(var i=0;i<hs.length;i++){\n      if(/We Model Human Perception/i.test(hs[i].textContent)){\n        var h=hs[i];\n        var spans=h.querySelectorAll('.sp-shimchar');\n        // two-tone: \"Human Perception\" (span 7 onward) -> translucent grey\n        for(var j=0;j<spans.length;j++){\n          if(j>=7){ spans[j].style.color='rgba(255,255,255,0.35)'; spans[j].style.webkitTextFillColor='rgba(255,255,255,0.35)'; }\n        }\n        // force \"Human\" onto a new line\n        if(!h.querySelector('br.np-forcebreak')){ if(spans[7]){\n          var br=document.createElement('br'); br.className='np-forcebreak';\n          h.insertBefore(br, spans[7]);\n        }}\n        return;\n      }\n    }\n  }\n  if(document.readyState!=='loading'){ styleTitle(); } else { document.addEventListener('DOMContentLoaded',styleTitle); }\n  setTimeout(styleTitle,500); setTimeout(styleTitle,1500);\n})();\n");
